describe('Search Suggestions Feature', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should display search suggestions for recently searched terms', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search/suggestions*').as('getSearchSuggestions');

    // Perform a search
    cy.get('[data-testid="search-input"]').type('cypress');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@getSearchSuggestions');

    // Verify suggestions are displayed
    cy.get('[data-testid="suggestion-list"]').should('be.visible');
    cy.get('[data-testid="suggestion-item"]').should('have.length.greaterThan', 0);

    // Verify suggestion text is correct
    cy.get('[data-testid="suggestion-item"]').first().should('contain', 'Cypress');

    // Verify suggestion link works
    cy.get('[data-testid="suggestion-item"]').first().click();
    cy.url().should('include', '/search/cypress');
  });

  it('should not display suggestions when no recent search terms exist', () => {
    // Clear search history
    cy.intercept('GET', '/api/search/suggestions*').as('getSearchSuggestions');
    cy.get('[data-testid="search-input"]').clear().type('');

    // Perform a search without typing anything
    cy.get('[data-testid="search-button"]').click();

    // Wait for the API response
    cy.wait('@getSearchSuggestions');

    // Verify no suggestions are displayed
    cy.get('[data-testid="suggestion-list"]').should('not.exist');

    // Verify search input is still visible
    cy.get('[data-testid="search-input"]').should('be.visible');
  });
});
